        function simulateInteraction() {
            if (activeGlyph === 'None') return;

            let pDelta = 0;
            let sDelta = 0;
            const prevBaseP = baseNodePotential;
            const prevBaseS = baseNodeSymmetry;

            // Interaction deltas (v19 - tuned for lasting impact)
            if (activeArc === 'Resonance') {
                switch(activeGlyph) {
