            baseNodePotential = Math.max(0, Math.min(1, baseNodePotential));
            baseNodeSymmetry = Math.max(0, Math.min(1, baseNodeSymmetry));

            console.log(`Simulate: Arc=${activeArc}, Glyph=${activeGlyph}`);
            console.log(`  Deltas: pD=${pDelta.toFixed(3)}, sD=${sDelta.toFixed(3)}`);
            console.log(`  Base Bef: pB=${prevBaseP.toFixed(3)}, sB=${prevBaseS.toFixed(3)}`);
