            const crystalScale = arcScale * (0.80 + (pot * 0.45));
            const potentialSaturation = 5 + Math.floor(pot * 95);
            const potentialLightness = 5 + Math.floor(pot * 65);
            const glowOpacity = 0.05 + (pot * 0.95 * arcGlowIntensity);
