            let currentRotationRad = parseFloat(resonantCrystal.style.getPropertyValue('--crystal-rotation-rad') || 0);
            let targetRotationRad = crystalTargetRotation;
            let rotationDiff = targetRotationRad - currentRotationRad;
            while (rotationDiff > Math.PI) rotationDiff -= 2 * Math.PI;
            while (rotationDiff < -Math.PI) rotationDiff += 2 * Math.PI;
            currentRotationRad += rotationDiff * 0.05;
            resonantCrystal.style.setProperty('--crystal-rotation-rad', currentRotationRad);
            resonantCrystal.style.setProperty('--crystal-rotation-final', `${currentRotationRad * (180/Math.PI)}deg`);

            let skewXVal = 0; let skewYVal = 0; let jitterX = '0px'; let jitterY = '0px';
