            else if (sym > 0.95) { outlineStdDev = 2.5; outlineCol = `hsla(0, 0%, 100%, ${0.85 + pot*0.15})`; }
            else if (sym > 0.82) { outlineStdDev = 2.0; outlineCol = `hsla(270, 100%, 95%, ${0.75 + pot*0.15})`; }
            else if (sym > 0.65) { outlineStdDev = 1.8; outlineCol = `hsla(270, 80%, 85%, ${0.65 + pot*0.15})`; }
            else { outlineStdDev = 1.5; outlineCol = `hsla(270, 70%, 80%, ${0.55 + pot*0.15})`; }

            if (useBroken && activeArc === 'Dissonance') { // Only use broken filter if truly dissonant and low symmetry
                feMorphologyBroken.setAttribute('stdDeviation', outlineStdDev);
