                    wallAnimDuration = `${Math.max(1.0, 7 * (1-symFactor) * (1-potFactor*0.6) )}s`;
                    floorAnimDuration = `${Math.max(1.0, 5 * (1-symFactor) * (1-potFactor*0.6) )}s`;
                    tileOpacity = 0.85 + potFactor * 0.15;
