        function applyNumericalBreath() {
            const currentTimeSeconds = Date.now() / 1000;
            const angularFrequency = (2 * Math.PI) / BREATH_PERIOD_SECONDS;

            let pAmp = BASE_BREATH_AMPLITUDE * activeArcData.breathFactor;
            let sAmp = BASE_BREATH_AMPLITUDE * activeArcData.breathFactor;

            if (activeArc === 'Dissonance') {
                pAmp += (Math.random() - 0.5) * BASE_BREATH_AMPLITUDE * 2.5;
                sAmp += (Math.random() - 0.5) * BASE_BREATH_AMPLITUDE * 2.5;
            } else if (activeArc === 'Resonance') {
                 const humFrequency = activeArcData.humSpeed * 35;
                 const humAmplitudeFactor = 0.35;
                 pAmp *= (1 + Math.sin(currentTimeSeconds * humFrequency + POTENTIAL_PHASE_OFFSET) * humAmplitudeFactor);
                 sAmp *= (1 + Math.cos(currentTimeSeconds * humFrequency + SYMMETRY_PHASE_OFFSET) * humAmplitudeFactor);
            }


            let potentialBreath = Math.sin(currentTimeSeconds * angularFrequency + POTENTIAL_PHASE_OFFSET) * pAmp;
            let symmetryBreath = Math.sin(currentTimeSeconds * angularFrequency + SYMMETRY_PHASE_OFFSET) * sAmp;

            if (baseNodePotential < REPULSION_THRESHOLD) potentialBreath += REPULSION_FORCE_MAGNITUDE * Math.pow((REPULSION_THRESHOLD - baseNodePotential) / REPULSION_THRESHOLD, 2);
            else if (baseNodePotential > (1 - REPULSION_THRESHOLD)) potentialBreath -= REPULSION_FORCE_MAGNITUDE * Math.pow((baseNodePotential - (1 - REPULSION_THRESHOLD)) / REPULSION_THRESHOLD, 2);

            if (baseNodeSymmetry < REPULSION_THRESHOLD) symmetryBreath += REPULSION_FORCE_MAGNITUDE * Math.pow((REPULSION_THRESHOLD - baseNodeSymmetry) / REPULSION_THRESHOLD, 2);
            else if (baseNodeSymmetry > (1 - REPULSION_THRESHOLD)) symmetryBreath -= REPULSION_FORCE_MAGNITUDE * Math.pow((baseNodeSymmetry - (1 - REPULSION_THRESHOLD)) / REPULSION_THRESHOLD, 2);

            if (activeArc === 'Dissonance') {
                if (Math.abs(baseNodePotential - 0.5) < MIDPOINT_REPULSION_THRESHOLD) potentialBreath += (baseNodePotential > 0.5 ? MIDPOINT_REPULSION_FORCE : -MIDPOINT_REPULSION_FORCE) * 1.5;
                if (Math.abs(baseNodeSymmetry - 0.5) < MIDPOINT_REPULSION_THRESHOLD) symmetryBreath += (baseNodeSymmetry > 0.5 ? MIDPOINT_REPULSION_FORCE : -MIDPOINT_REPULSION_FORCE) * 1.5;
            }

            currentNodePotential = Math.max(0, Math.min(1, baseNodePotential + potentialBreath));
            currentNodeSymmetry = Math.max(0, Math.min(1, baseNodeSymmetry + symmetryBreath));

            updateEssenceDisplays();
        }

        function updatePlayerModelPosition() {
