            const maxPlayerY = FLOOR_HEIGHT_PERCENT - playerSpriteHeightPercent;
            playerPositionY = Math.max(0, Math.min(playerPositionY, maxPlayerY > 0 ? maxPlayerY : 0));
            const playerSpriteWidthPercent = (parseFloat(playerModel.style.width) || 30) / gameWindow.clientWidth * 100;
            playerPositionX = Math.max(0, Math.min(playerPositionX, 100 - playerSpriteWidthPercent));
